const items = $input.all();
const output = [];

const TIME_ZONE = 'Asia/Seoul';


// -----------------------------------------
// 현재 한국 날짜/시간
// -----------------------------------------
function getKSTParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TIME_ZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);

  const get = (type) =>
    parts.find(p => p.type === type)?.value;

  return {
    year: get('year'),
    month: get('month'),
    day: get('day'),
    hour: Number(get('hour')),
    minute: Number(get('minute')),
  };
}


// -----------------------------------------
// YYYY-MM-DD 유효성 검사
// -----------------------------------------
function isValidDateString(value) {
  if (
    typeof value !== 'string' ||
    !/^\d{4}-\d{2}-\d{2}$/.test(value)
  ) {
    return false;
  }

  const [year, month, day] =
    value.split('-').map(Number);

  const date =
    new Date(Date.UTC(year, month - 1, day));

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}


// -----------------------------------------
// YYYY-MM-DD 기준 하루 빼기
// -----------------------------------------
function subtractOneDay(dateString) {
  const date =
    new Date(`${dateString}T00:00:00Z`);

  date.setUTCDate(
    date.getUTCDate() - 1
  );

  return date.toISOString().slice(0, 10);
}


// -----------------------------------------
// 한국 시간 ISO 문자열 생성
// -----------------------------------------
function makeKSTDateTime(dateString, hour) {
  const hh =
    String(hour).padStart(2, '0');

  return `${dateString}T${hh}:00:00+09:00`;
}


// -----------------------------------------
// 일정 미생성 결과
// -----------------------------------------
function notScheduled({
  reason,
  consultation_id = null,
  customer_id = null,
  preferred_follow_up_date = null,
}) {
  return {
    json: {
      success: true,
      feature_id: 'F-06',
      status: 'not_scheduled',
      reason,
      schedule_type: 'reconsultation',
      consultation_id,
      customer_id,
      preferred_follow_up_date,
    }
  };
}


// -----------------------------------------
// 현재 한국 시간
// -----------------------------------------
const nowKST = getKSTParts();

const todayString =
  `${nowKST.year}-${nowKST.month}-${nowKST.day}`;

const currentMinutes =
  (nowKST.hour * 60) + nowKST.minute;


// 발송 슬롯
const SLOT_10 = 10 * 60;
const SLOT_16 = 16 * 60;
const SLOT_19 = 19 * 60;


// -----------------------------------------
// 각 상담 처리
// -----------------------------------------
for (const item of items) {

  const {
    consultation_id,
    customer_id,
    customer_name,

    preferred_follow_up_date,
    contact_reason,

    store_id,
    staff_id,

    privacy_consent,
    recontact_consent,

    schedule_type,
  } = item.json;


  // 상담 조회 실패
  if (!consultation_id || !customer_id) {
    output.push(
      notScheduled({
        reason: 'consultation_not_found',
        consultation_id,
        customer_id,
      })
    );

    continue;
  }


  // 동의 없음
  if (
    privacy_consent !== true ||
    recontact_consent !== true
  ) {
    output.push(
      notScheduled({
        reason: 'consent_missing',
        consultation_id,
        customer_id,
        preferred_follow_up_date,
      })
    );

    continue;
  }


  // 재상담 희망 날짜 없음
  if (!preferred_follow_up_date) {
    output.push(
      notScheduled({
        reason: 'follow_up_date_missing',
        consultation_id,
        customer_id,
      })
    );

    continue;
  }


  // 날짜 형식 오류
  if (
    !isValidDateString(
      preferred_follow_up_date
    )
  ) {
    output.push(
      notScheduled({
        reason: 'invalid_follow_up_date',
        consultation_id,
        customer_id,
        preferred_follow_up_date,
      })
    );

    continue;
  }


  const reconsultationDate =
    preferred_follow_up_date;


  // 재상담일이 오늘 또는 과거
  if (
    reconsultationDate <= todayString
  ) {
    output.push(
      notScheduled({
        reason: 'date_passed',
        consultation_id,
        customer_id,
        preferred_follow_up_date,
      })
    );

    continue;
  }


  // 재상담 하루 전
  const reminderDate =
    subtractOneDay(
      reconsultationDate
    );


  let scheduledHour = null;


  // D-1이 미래 날짜
  if (reminderDate > todayString) {

    scheduledHour = 10;

  }


  // D-1이 오늘
  else if (
    reminderDate === todayString
  ) {

    if (currentMinutes < SLOT_10) {
      scheduledHour = 10;
    }

    else if (
      currentMinutes < SLOT_16
    ) {
      scheduledHour = 16;
    }

    else if (
      currentMinutes < SLOT_19
    ) {
      scheduledHour = 19;
    }

    else {
      output.push(
        notScheduled({
          reason: 'send_slot_passed',
          consultation_id,
          customer_id,
          preferred_follow_up_date,
        })
      );

      continue;
    }

  }


  // D-1 자체가 이미 지난 경우
  else {
    output.push(
      notScheduled({
        reason: 'reminder_date_passed',
        consultation_id,
        customer_id,
        preferred_follow_up_date,
      })
    );

    continue;
  }


  const scheduledContactAt =
    makeKSTDateTime(
      reminderDate,
      scheduledHour
    );


  // -----------------------------------------
  // 최종 재상담 스케줄
  // -----------------------------------------
  output.push({
    json: {
      consultation_id,
      customer_id,
      customer_name,

      store_id,
      staff_id,

      schedule_type:
        schedule_type ?? 'reconsultation',

      privacy_consent,
      recontact_consent,

      preferred_follow_up_date,

      reference_date:
        reconsultationDate,

      schedule_subtype:
        'reconsultation_1d_before',

      scheduled_contact_date:
        reminderDate,

      scheduled_contact_at:
        scheduledContactAt,

      contact_reason:
        contact_reason ??
        '재상담 1일 전 안내',

      selected_send_slot:
        `${String(scheduledHour).padStart(2, '0')}:00`
    }
  });
}


return output;

const saved = $('재상담 스케줄 저장').item.json;

return [
  {
    json: {
      success: true,
      feature_id: 'F-06',
      status: 'scheduled',

      schedule_id: saved.schedule_id ?? null,
      customer_id: saved.customer_id ?? null,

      schedule_type:
        saved.schedule_type ?? 'reconsultation',

      schedule_subtype:
        saved.schedule_subtype ?? null,

      consultation_id:
        saved.consultation_id ?? null,

      scheduled_contact_at:
        saved.scheduled_contact_at ?? null,

      contact_reason:
        saved.contact_reason ?? null
    }
  }
];
